<script setup>
import{computed,onMounted,provide,reactive,ref,watch}from'vue';import{useRoute}from'vue-router';import IconMenu from'~icons/lucide/menu';import IconRefresh from'~icons/lucide/refresh-cw';import IconSearch from'~icons/lucide/search';import IconHome from'~icons/lucide/layout-dashboard';import IconShip from'~icons/lucide/ship';import IconTruck from'~icons/lucide/truck';import IconShopping from'~icons/lucide/shopping-cart';import IconUsers from'~icons/lucide/users';import{boot,call,__}from'./api';
const route=useRoute(),ctx=reactive({companies:[],company:null,permissions:{},ready:false}),navOpen=ref(false),refreshKey=ref(0),q=ref(''),results=ref([]),searching=ref(false);provide('portal',{ctx,refreshKey});
const groups=computed(()=>[{label:__('Dashboard'),items:[{to:'/',label:__('Home'),icon:IconHome}]},{label:__('Import Management'),items:[{to:'/import-files',label:__('Vehicle Import Files'),icon:IconShip,dt:'Vehicle Import File'}]},{label:__('Purchasing'),items:[['/suppliers','Suppliers','Supplier'],['/purchase-orders','Purchase Orders','Purchase Order'],['/purchase-receipts','Purchase Receipts','Purchase Receipt'],['/purchase-invoices','Purchase Invoices','Purchase Invoice'],['/supplier-payments','Supplier Payments','Payment Entry'],['/landed-costs','Landed Cost Vouchers','Landed Cost Voucher']].map(x=>({to:x[0],label:__(x[1]),dt:x[2],icon:IconShopping}))},{label:__('Vehicles'),items:[['/vehicles','Vehicle Master','Vehicle Master'],['/serials','VIN and Serial Numbers','Serial No'],['/inspections','Vehicle Inspections','Quality Inspection']].map(x=>({to:x[0],label:__(x[1]),dt:x[2],icon:IconTruck}))},{label:__('Sales'),items:[['/customers','Customers','Customer'],['/quotations','Quotations','Quotation'],['/sales-orders','Sales Orders','Sales Order'],['/sales-invoices','Sales Invoices','Sales Invoice'],['/customer-payments','Customer Payments','Payment Entry']].map(x=>({to:x[0],label:__(x[1]),dt:x[2],icon:IconUsers}))}].map(g=>({...g,items:g.items.filter(i=>!i.dt||ctx.permissions[i.dt]?.read)})).filter(g=>g.items.length));
onMounted(async()=>{if(boot.allowed){Object.assign(ctx,await call('an_truck_portal.api.context.get_context'));ctx.company=ctx.default_company;ctx.ready=true}});watch(()=>route.fullPath,()=>navOpen.value=false);let timer;watch(q,v=>{clearTimeout(timer);results.value=[];if(v.length>1)timer=setTimeout(async()=>{searching.value=true;try{results.value=await call('an_truck_portal.api.search.search',{q:v})}finally{searching.value=false}},250)});
</script>
<template><main v-if="!boot.allowed" class="center"><div class="panel"><img src="/assets/an_truck_portal/logo.svg" width="48"><h1>{{boot.app_title}}</h1><p>{{__('You do not have access to this portal.')}}</p><a href="/app">{{__('Open Desk')}}</a></div></main><div v-else class="shell"><aside :class="['sidebar',{open:navOpen}]"><div class="brand"><img src="/assets/an_truck_portal/logo.svg"><div><b>{{boot.app_title}}</b><small>{{ctx.company}}</small></div></div><nav v-for="g in groups" :key="g.label"><label>{{g.label}}</label><router-link v-for="i in g.items" :to="i.to"><component :is="i.icon"/><span>{{i.label}}</span></router-link></nav><footer><a href="/app">{{__('Open Desk')}}</a><a href="/?cmd=web_logout">{{__('Sign out')}}</a></footer></aside><div class="overlay" v-if="navOpen" @click="navOpen=false"/><section class="main"><header><button class="icon mobile" @click="navOpen=true"><IconMenu/></button><div class="search"><IconSearch/><input v-model="q" :placeholder="__('Search VIN, file, supplier, customer…')"><div class="search-results" v-if="q.length>1"><p v-if="searching">{{__('Searching…')}}</p><router-link v-for="r in results" :to="r.doctype==='Vehicle Master'?`/vehicles/${r.name}`:r.doctype==='Vehicle Import File'?`/import-files/${r.name}`:'#'" @click="q=''">{{r.label}}<small>{{r.doctype}} · {{r.name}}</small></router-link><p v-if="!searching&&!results.length">{{__('No results')}}</p></div></div><select v-if="ctx.companies.length" v-model="ctx.company"><option value="">{{__('All companies')}}</option><option v-for="c in ctx.companies" :value="c.name">{{c.name}}</option></select><button class="icon" @click="refreshKey++"><IconRefresh/></button><div class="user">{{boot.full_name}}</div></header><router-view :key="`${route.fullPath}-${ctx.company}-${refreshKey}`"/></section></div></template>
